<div class="card shadow-sm mb-4"><div class="card-body"><form method="post" action="<?= base_url('admin/livestream/store') ?>" class="row g-2 align-items-end"><?= csrf_field() ?><div class="col-md-2"><label class="form-label">Tên kênh</label><input name="name" class="form-control" maxlength="180" required></div><div class="col-md-2"><label class="form-label">Nhà cung cấp</label><select name="provider" class="form-select"><option value="youtube">YouTube</option><option value="facebook">Facebook</option><option value="custom">Custom</option></select></div><div class="col-md-2"><label class="form-label">Stream URL</label><input type="url" name="stream_url" class="form-control" placeholder="https://..." required></div><div class="col-md-2"><label class="form-label">Embed URL</label><input type="url" name="embed_url" class="form-control" placeholder="https://..." required></div><div class="col-md-1"><label class="form-label">Chi nhánh</label><select name="branch_id" class="form-select"><option value="">-</option><?php foreach ($branches as $branch): ?><option value="<?= (int) $branch->id ?>"><?= esc($branch->name) ?></option><?php endforeach; ?></select></div><div class="col-md-1"><label class="form-label">Trạng thái</label><select name="status" class="form-select"><option value="draft">Nháp</option><option value="scheduled">Đã lịch</option></select></div><div class="col-md-2"><label class="form-label">Thời gian</label><input type="datetime-local" name="scheduled_at" class="form-control"><button class="btn btn-primary mt-2 w-100">Tạo kênh</button></div></form></div></div>
